      state: 'an order exists with shipping info',
      uponReceiving: 'a request for order details',
      withRequest: { method: 'GET', path: '/orders/123' },
      willRespondWith: {
        status: 200,
        body: {
          id: '123',
          customerNote: 'Please leave at door', // deprecated but present
          shipEta: '2024-12-25T10:00:00Z' // new optional field
        }
      }
    });

    const response = await axios.get(`${provider.mockService.baseUrl}/orders/123`);
    expect(response.data).to.have.property('shipEta');
    expect(response.data.customerNote).to.not.be.undefined; // backward compat
